	class Admin_JS_I18n {

		/**
		 * Get English->translated map for admin JS.
		 *
		 * Reads the plugin .mo directly so translations apply even when WP JIT
		 * textdomain loading has not registered the domain yet.
		 *
		 * @return array<string, string>
		 */
		public static function get_map() {
			$domain = 'change-wp-admin-login';
			$locale = function_exists( 'determine_locale' ) ? determine_locale() : get_locale();
			$mo_map = self::load_mo_translations( $domain, $locale );

			self::ensure_textdomain_loaded( $domain, $locale );

			$map = array();
			foreach ( self::get_strings() as $string ) {
				if ( isset( $mo_map[ $string ] ) && '' !== $mo_map[ $string ] ) {
					$map[ $string ] = $mo_map[ $string ];
					continue;
				}
				$map[ $string ] = translate( $string, $domain ); // phpcs:ignore WordPress.WP.I18n.NonSingularString
			}
			return $map;
		}

		/**
		 * @param string $domain Text domain.
		 * @param string $locale Locale.
		 * @return array<string, string>
		 */
		private static function load_mo_translations( $domain, $locale ) {
			$candidates = array();
			if ( defined( 'WP_LANG_DIR' ) ) {
				$candidates[] = WP_LANG_DIR . '/plugins/' . $domain . '-' . $locale . '.mo';
				$candidates[] = WP_LANG_DIR . '/' . $domain . '-' . $locale . '.mo';
			}
			$candidates[] = AIO_LOGIN__DIR_PATH . 'languages/' . $domain . '-' . $locale . '.mo';
			if ( false !== strpos( $locale, '_' ) ) {
				$short = strtok( $locale, '_' );
				if ( defined( 'WP_LANG_DIR' ) ) {
					$candidates[] = WP_LANG_DIR . '/plugins/' . $domain . '-' . $short . '.mo';
				}
				$candidates[] = AIO_LOGIN__DIR_PATH . 'languages/' . $domain . '-' . $short . '.mo';
			}

			foreach ( $candidates as $mofile ) {
				if ( ! is_readable( $mofile ) ) {
					continue;
				}
				$parsed = self::parse_mo_file( $mofile );
				if ( ! empty( $parsed ) ) {
					return $parsed;
				}
			}
			return array();
		}

		/**
		 * @param string $path Path.
		 * @return array<string, string>
		 */
		private static function parse_mo_file( $path ) {
			$data = file_get_contents( $path );
			if ( false === $data || strlen( $data ) < 28 ) {
				return array();
			}
			$header = unpack( 'Vmagic/Vrevision/Vcount/Vot/Vtt', substr( $data, 0, 20 ) );
			if ( empty( $header ) || 0x950412de !== (int) $header['magic'] ) {
				return array();
			}
			$count = (int) $header['count'];
			$ot    = (int) $header['ot'];
			$tt    = (int) $header['tt'];
			$map   = array();
			for ( $i = 0; $i < $count; $i++ ) {
				$o = unpack( 'Vlen/Voff', substr( $data, $ot + ( $i * 8 ), 8 ) );
				$t = unpack( 'Vlen/Voff', substr( $data, $tt + ( $i * 8 ), 8 ) );
				if ( empty( $o ) || empty( $t ) ) {
					continue;
				}
				$id  = substr( $data, $o['off'], $o['len'] );
				$str = substr( $data, $t['off'], $t['len'] );
				if ( false === $id || false === $str || '' === $id ) {
					continue;
				}
				if ( false !== strpos( $id, "\0" ) ) {
					$id = strtok( $id, "\0" );
				}
				if ( false !== strpos( $str, "\0" ) ) {
					$str = strtok( $str, "\0" );
				}
				$map[ $id ] = $str;
			}
			return $map;
		}

		/**
		 * @param string $domain Text domain.
		 * @param string $locale Locale.
		 */
		private static function ensure_textdomain_loaded( $domain, $locale ) {
			$mofile = AIO_LOGIN__DIR_PATH . 'languages/' . $domain . '-' . $locale . '.mo';
			if ( is_readable( $mofile ) ) {
				load_textdomain( $domain, $mofile );
			}
			load_plugin_textdomain(
				$domain,
				false,
				dirname( plugin_basename( AIO_LOGIN__FILE ) ) . '/languages'
			);
		}

